% toon0231 -- Visualize Wavelet Xform%%  Here we display a 2-d image (a stick figure)%  and its 2-d wavelet transform.%	stick = Make2dSignal('StickFigure', 128);%	clf; subplot(121);	AutoImage(stick);	title('Skinny');%	Q = MakeONFilter('Coiflet',2);	wstick = FWT2_PO(stick,3,Q);%	subplot(122);	zmat = sqrt(abs(wstick));	zmat = 256-3.8*zmat;	AutoImage(zmat);	title('WT2[Skinny]');        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       